# 提为模块常量，便于按 shape 分档与批量配置扫描；默认值保持原实现。
_RANDINT_BLOCK_SIZE = 4096
_RANDINT_UNROLL = 4
_RANDINT_MAX_GRID_X = 65535
_RANDINT_NUM_WARPS = 4
# 32 位取模比 64 位除法便宜得多；high < 2**32 时启用，否则保持原 64 位路径。
_RANDINT_U32_HIGH_LIMIT = 1 << 32


