        r1_mod = (r1 % high_val).to(out_ptr.dtype.element_ty)
        r2_mod = (r2 % high_val).to(out_ptr.dtype.element_ty)
        r3_mod = (r3 % high_val).to(out_ptr.dtype.element_ty)

